"""Build checks use generated bytes, never commercial ROM/runtime fixtures."""
import hashlib
import io
import json
from pathlib import Path
import tarfile
import zipfile

import pytest

from scripts import fetch_runtime as runtime
from scripts.check_public_source import violations


def fixture_cache(tmp_path):
    vendor = tmp_path / 'vendor'
    archive = vendor / 'runtime-downloads/demo_libretro.so.zip'
    archive.parent.mkdir(parents=True)
    binary = b'generated test-only runtime payload'
    with zipfile.ZipFile(archive, 'w') as output:
        output.writestr('demo_libretro.so', binary)
    entries = {'demo_libretro.so.zip': {
        'url': 'https://example.invalid/demo_libretro.so.zip',
        'sha256': runtime.digest(archive),
        'binary_sha256': hashlib.sha256(binary).hexdigest(),
    }}
    lock = tmp_path / 'runtime-lock.json'
    lock.write_text(json.dumps(entries))
    return vendor, archive, entries, lock


def test_offline_materialize_preserves_reviewed_lock(tmp_path, monkeypatch):
    vendor, archive, entries, lock = fixture_cache(tmp_path)
    original = lock.read_bytes()
    monkeypatch.setattr(runtime.subprocess, 'run', lambda *args, **kwargs: pytest.fail('offline path attempted network'))
    paths = dict([runtime.fetch_one(vendor, 'demo_libretro.so.zip', entries['demo_libretro.so.zip'], True)])
    runtime.materialize(paths, entries, vendor)
    assert (vendor / 'libretro/demo_libretro.so').read_bytes() == b'generated test-only runtime payload'
    assert lock.read_bytes() == original
    archive.write_bytes(b'mutable upstream changed')
    with pytest.raises(ValueError, match='SHA256 mismatch'):
        runtime.fetch_one(vendor, 'demo_libretro.so.zip', entries['demo_libretro.so.zip'], False)
    assert lock.read_bytes() == original


def test_offline_missing_never_fetches(tmp_path, monkeypatch):
    vendor, archive, entries, _ = fixture_cache(tmp_path)
    archive.unlink()
    monkeypatch.setattr(runtime.subprocess, 'run', lambda *args, **kwargs: pytest.fail('offline path attempted network'))
    with pytest.raises(ValueError, match='incomplete'):
        runtime.fetch_one(vendor, 'demo_libretro.so.zip', entries['demo_libretro.so.zip'], True)


def test_private_backup_restores_only_locked_files(tmp_path):
    vendor, archive, entries, lock = fixture_cache(tmp_path)
    (vendor / 'secret-save.sav').write_bytes(b'private user data')
    bundle = tmp_path / 'private-cache.tar.gz'
    runtime.create_bundle(bundle, lock, entries, vendor)
    with tarfile.open(bundle) as contents:
        assert set(contents.getnames()) == {'runtime-lock.json', 'archives/demo_libretro.so.zip'}
    fresh = tmp_path / 'fresh-vendor'
    runtime.restore_bundle(bundle, lock, entries, fresh)
    assert runtime.digest(fresh / 'runtime-downloads/demo_libretro.so.zip') == runtime.digest(archive)
    assert not (fresh / 'secret-save.sav').exists()
    other = tmp_path / 'other-lock.json'; other.write_text('{}')
    with pytest.raises(ValueError, match='another reviewed lock'):
        runtime.restore_bundle(bundle, other, entries, fresh)


def test_private_backup_rejects_extra_and_symlink_entries(tmp_path):
    vendor, _, entries, lock = fixture_cache(tmp_path)
    bundle = tmp_path / 'bad.tar.gz'
    with tarfile.open(bundle, 'w:gz') as output:
        item = tarfile.TarInfo('../../escape'); item.size = 1
        output.addfile(item, io.BytesIO(b'x'))
    with pytest.raises(ValueError, match='Unexpected'):
        runtime.restore_bundle(bundle, lock, entries, vendor)
    with tarfile.open(bundle, 'w:gz') as output:
        item = tarfile.TarInfo('runtime-lock.json'); item.type = tarfile.SYMTYPE; item.linkname = '/etc/passwd'
        output.addfile(item)
        item = tarfile.TarInfo('archives/demo_libretro.so.zip'); item.size = 0; output.addfile(item, io.BytesIO())
    with pytest.raises(ValueError, match='Unsafe'):
        runtime.restore_bundle(bundle, lock, entries, vendor)


@pytest.mark.parametrize('name', ['../escape', '/absolute', 'C:/drive', 'folder\\escape', 'bad\x00name'])
def test_zip_extraction_rejects_unsafe_paths(tmp_path, name):
    with pytest.raises(ValueError, match='Unsafe'):
        runtime.safe_member(name)


def test_extract_rejects_symlink_parent_and_oversize(tmp_path, monkeypatch):
    archive = tmp_path / 'asset.zip'
    with zipfile.ZipFile(archive, 'w') as output: output.writestr('folder/data', b'12345')
    root = tmp_path / 'root'; root.mkdir()
    outside = tmp_path / 'outside'; outside.mkdir()
    (root / 'folder').symlink_to(outside, target_is_directory=True)
    with pytest.raises(ValueError, match='symlink'):
        runtime.extract_zip(archive, root)
    assert not list(outside.iterdir())
    monkeypatch.setattr(runtime, 'MAX_ASSET_BYTES', 4)
    with pytest.raises(ValueError, match='Oversized'):
        runtime.extract_zip(archive, tmp_path / 'safe')


def test_lock_rejects_unreviewed_hash_and_url(tmp_path):
    _, _, entries, _ = fixture_cache(tmp_path)
    assert len(runtime.records(entries)) == 1
    entries['demo_libretro.so.zip']['url'] = 'http://example.invalid/core.zip'
    with pytest.raises(ValueError, match='HTTPS'): runtime.records(entries)
    entries['demo_libretro.so.zip']['url'] = 'https://example.invalid/core.zip'
    entries['demo_libretro.so.zip']['sha256'] = 'replace with latest'
    with pytest.raises(ValueError, match='SHA256'): runtime.records(entries)


def test_public_source_rejects_private_payload_and_unreviewed_image(tmp_path):
    assert len(violations(['vendor/core.txt', 'roms/example.txt', 'user.nes', '.env', 'docs/game.png'], tmp_path)) == 5
    (tmp_path / 'web').mkdir(); (tmp_path / 'web/app.js').write_text('const x = 1;')
    assert not violations(['web/app.js'], tmp_path)


@pytest.mark.parametrize('name', [
    'assets/content.nca', 'assets/homebrew.NRO', 'assets/program.nso',
    'assets/backup.NSZ', 'assets/backup.xcz', 'assets/process.kip',
    'assets/program.npdm', 'assets/content.pfs0', 'assets/content.hfs0',
    'assets/content.nax0', 'assets/content.tik', 'assets/content.ticket',
    'assets/device.cert', 'assets/custom.keys', 'assets/PROD.KEYS',
    'assets/title.keys.bak', 'assets/prod.keys_autogenerated',
    'assets/console.keys_autogenerated.txt', 'assets/dev.keys.txt',
    'assets/PRODINFO', 'assets/BOOT0', 'assets/boot1.backup',
    'assets/game.nsp.txt', 'assets/game.XCI.backup', 'Firmware/readme.txt',
])
def test_public_source_rejects_switch_assets_even_text_or_renamed(tmp_path, name):
    payload = tmp_path / name
    payload.parent.mkdir(parents=True, exist_ok=True)
    # No real key or game data: extension/name policy must not rely on NUL bytes.
    payload.write_text('generated placeholder, not a console asset')
    assert len(violations([name], tmp_path)) == 1


def test_switch_source_and_preparation_docs_remain_publishable(tmp_path):
    names = ['retroone/switch_runtime.py', 'docs/switch-runtime.md',
             'container/eden', 'container/runtime-lock.json', '.env.example']
    for name in names:
        path = tmp_path / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('generated source/doc placeholder; no runtime asset')
    assert not violations(names, tmp_path)


def test_screenshot_manifest_matches_exact_reviewed_bytes(tmp_path):
    folder = tmp_path / 'docs/screenshots'; folder.mkdir(parents=True)
    image = folder / 'library.png'; image.write_bytes(b'\x89PNG\0generated fixture pixels')
    manifest = {'source': 'self-rendered fixtures', 'files': [{'path': 'library.png', 'sha256': hashlib.sha256(image.read_bytes()).hexdigest()}]}
    (folder / 'manifest.json').write_text(json.dumps(manifest))
    assert not violations(['docs/screenshots/library.png'], tmp_path)
    image.write_bytes(b'\x89PNG\0different unreviewed pixels')
    errors = violations(['docs/screenshots/library.png'], tmp_path)
    assert any('SHA256 mismatch' in reason for _, reason in errors)


def test_product_icons_require_own_mark_and_exact_reviewed_bytes(tmp_path):
    folder = tmp_path / 'web/icons'
    folder.mkdir(parents=True)
    source = tmp_path / 'web/favicon.svg'
    source.write_text('<svg xmlns="http://www.w3.org/2000/svg"/>')
    icon = folder / 'icon-192.png'
    icon.write_bytes(b'\x89PNG\0generated application mark')
    manifest = {'source': 'web/favicon.svg', 'source_sha256': hashlib.sha256(source.read_bytes()).hexdigest(),
                'files': [{'path': icon.name, 'sha256': hashlib.sha256(icon.read_bytes()).hexdigest()}]}
    (folder / 'manifest.json').write_text(json.dumps(manifest))
    assert not violations(['web/icons/icon-192.png'], tmp_path)
    # A replacement of either the reviewed vector or rendered icon must fail.
    icon.write_bytes(b'\x89PNG\0unreviewed artwork')
    assert violations(['web/icons/icon-192.png'], tmp_path)
    manifest['files'][0]['sha256'] = hashlib.sha256(icon.read_bytes()).hexdigest()
    (folder / 'manifest.json').write_text(json.dumps(manifest))
    source.write_text('<svg>different mark</svg>')
    assert violations(['web/icons/icon-192.png'], tmp_path)
    # This manifest is not an escape hatch for unrelated cover caches.
    manifest['source_sha256'] = hashlib.sha256(source.read_bytes()).hexdigest()
    manifest['files'][0]['path'] = 'cover.png'
    (folder / 'manifest.json').write_text(json.dumps(manifest))
    assert violations(['web/icons/cover.png'], tmp_path)
